# Taking Screenshots With Playwright: A Beginner’s Guide
## Setting Up Playwright
```javascript
node -v
npm -v
```

```javascript
npm init -y
```

```javascript
npm install playwright
```

## Full Page Screenshot Example
```javascript
const { chromium } = require('playwright');

(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage();

  await page.goto('https://iproyal.com/');

  // Capture the entire page
  await page.screenshot({
    path: 'full-page.png',
    fullPage: true
  });

  await browser.close();
})();
```

```javascript
await page.screenshot({
  path: 'screenshot.jpg',
  fullPage: true,
  quality: 80  // 80% quality
});
```

## Capturing a Specific Element
```javascript
await page.locator('#hero-header-block').screenshot({
  path: 'hero-header-block.jpg',
  quality: 85
});
```

## Screenshots in Playwright Reports
```javascript
module.exports = {
  use: {
    // Options: 'on', 'off', 'only-on-failure'
    screenshot: 'only-on-failure',
  },
};
```

## Method 2: Playwright
### Basic Screenshot
```
const { chromium } = require('playwright');

async function takeScreenshot(url, outputPath) {
  const browser = await chromium.launch();
  const page = await browser.newPage();
  await page.goto(url, { waitUntil: 'networkidle' });
  await page.screenshot({ path: outputPath });
  await browser.close();
}

takeScreenshot('https://example.com', 'screenshot.png');
```

### Cross-Browser Screenshots
```
const { chromium, firefox, webkit } = require('playwright');

async function crossBrowserScreenshots(url) {
  for (const browserType of [chromium, firefox, webkit]) {
    const browser = await browserType.launch();
    const page = await browser.newPage();
    await page.goto(url, { waitUntil: 'networkidle' });
    await page.screenshot({
      path: `screenshot-${browserType.name()}.png`
    });
    await browser.close();
  }
}

crossBrowserScreenshots('https://example.com');
```

### Device Emulation
```
const { chromium, devices } = require('playwright');

const iPhone = devices['iPhone 14'];

async function mobileScreenshot(url) {
  const browser = await chromium.launch();
  const context = await browser.newContext({ ...iPhone });
  const page = await context.newPage();
  await page.goto(url, { waitUntil: 'networkidle' });
  await page.screenshot({ path: 'mobile.png' });
  await browser.close();
}
```

# Screenshot API Comparison: Puppeteer vs Playwright vs CustomJS (2026)
## Puppeteer: screenshot example
### Node.js (Puppeteer)
```javascript
const puppeteer = require('puppeteer');

async function screenshotWithPuppeteer(url) {
  const browser = await puppeteer.launch({
    headless: 'new'
  });

  try {
    const page = await browser.newPage();

    await page.setViewport({ width: 1280, height: 720 });
    await page.goto(url, { waitUntil: 'networkidle2', timeout: 30000 });

    // Example: click cookie banner (update selector for your site)
    // await page.click('#accept-cookies');

    await page.waitForTimeout(500);

    await page.screenshot({ path: 'screenshot.png', fullPage: true });
  } finally {
    await browser.close();
  }
}

screenshotWithPuppeteer('https://example.com');
```

## Playwright: screenshot example
### Node.js (Playwright)
```javascript
const { chromium } = require('playwright');

async function screenshotWithPlaywright(url) {
  const browser = await chromium.launch();

  try {
    const page = await browser.newPage({ viewport: { width: 1280, height: 720 } });
    await page.goto(url, { waitUntil: 'networkidle', timeout: 30000 });

    // Example: wait for a selector to appear
    // await page.waitForSelector('main');

    await page.screenshot({ path: 'screenshot.png', fullPage: true });
  } finally {
    await browser.close();
  }
}

screenshotWithPlaywright('https://example.com');
```

## Introduction [​](https://playwright.dev/docs/test-snapshots#introduction)
```js
import { test, expect } from '@playwright/test';

test('example test', async ({ page }) => {

  await page.goto('https://playwright.dev');

  await expect(page).toHaveScreenshot();

});
```

## Generating screenshots [​](https://playwright.dev/docs/test-snapshots#generating-screenshots)
```js
await expect(page).toHaveScreenshot('landing.webp');
```

## Updating screenshots [​](https://playwright.dev/docs/test-snapshots#updating-screenshots)
```bash
npx playwright test --update-snapshots
```

## Options [​](https://playwright.dev/docs/test-snapshots#options)
### stylePath [​](https://playwright.dev/docs/test-snapshots#stylepath)
```js
import { test, expect } from '@playwright/test';

test('example test', async ({ page }) => {

  await page.goto('https://playwright.dev');

  await expect(page).toHaveScreenshot({ stylePath: path.join(__dirname, 'screenshot.css') });

});
```
